javascript:
frappe.query_reports["Kenaikan & Kelulusan Calistung"] = {
    filters: [
        { fieldname: "dari_tanggal", label: __("Dari Tanggal"), fieldtype: "Date" },
        { fieldname: "sampai_tanggal", label: __("Sampai Tanggal"), fieldtype: "Date" },
    ],
};

report_script:
filters = filters or {}

codes = frappe.get_all(
    "Rumba Program Belajar",
    filters={"program_belajar": ["like", "%alistung%"]},
    pluck="name",
) or ["BMSK"]

ujian_filters = {
    "hasil": "Lulus",
    "status_ujian": "Final",
    "program": ["in", codes],
}
dari = filters.get("dari_tanggal")
sampai = filters.get("sampai_tanggal")
if dari and sampai:
    ujian_filters["tanggal_ujian"] = ["between", [dari, sampai]]
elif dari:
    ujian_filters["tanggal_ujian"] = [">=", dari]
elif sampai:
    ujian_filters["tanggal_ujian"] = ["<=", sampai]

rows = frappe.get_list(
    "Rumba Ujian Kenaikan Level",
    filters=ujian_filters,
    fields=["murid", "nama_unit", "level_diuji"],
    limit_page_length=0,
)

units = {}
for r in rows:
    unit = r.nama_unit or "(Tanpa Unit)"
    u = units.setdefault(unit, {"naik_l2": set(), "naik_l3": set(), "lulus": set()})
    if r.level_diuji == "Level 1":
        u["naik_l2"].add(r.murid)
    elif r.level_diuji == "Level 2":
        u["naik_l3"].add(r.murid)
    elif r.level_diuji == "Level 3":
        u["lulus"].add(r.murid)

data = []
tot = {"naik_l2": 0, "naik_l3": 0, "lulus": 0}
for unit in sorted(units):
    u = units[unit]
    naik_l2, naik_l3, lulus = len(u["naik_l2"]), len(u["naik_l3"]), len(u["lulus"])
    data.append({
        "unit": unit, "naik_l2": naik_l2, "naik_l3": naik_l3,
        "total_kenaikan": naik_l2 + naik_l3, "lulus": lulus,
    })
    tot["naik_l2"] = tot["naik_l2"] + naik_l2
    tot["naik_l3"] = tot["naik_l3"] + naik_l3
    tot["lulus"] = tot["lulus"] + lulus

if data:
    data.append({
        "unit": "TOTAL", "naik_l2": tot["naik_l2"], "naik_l3": tot["naik_l3"],
        "total_kenaikan": tot["naik_l2"] + tot["naik_l3"], "lulus": tot["lulus"],
    })

columns = [
    {"fieldname": "unit", "label": "Unit", "fieldtype": "Link", "options": "Rumba Unit", "width": 180},
    {"fieldname": "naik_l2", "label": "Naik ke Level 2 (Binar)", "fieldtype": "Int", "width": 160},
    {"fieldname": "naik_l3", "label": "Naik ke Level 3 (Lancar)", "fieldtype": "Int", "width": 160},
    {"fieldname": "total_kenaikan", "label": "Total Naik Tingkat", "fieldtype": "Int", "width": 140},
    {"fieldname": "lulus", "label": "Lulus Program (Level 3)", "fieldtype": "Int", "width": 160},
]

if data:
    report_summary = [
        {"value": tot["naik_l2"] + tot["naik_l3"], "label": "Total Naik Tingkat", "datatype": "Int", "indicator": "Blue"},
        {"value": tot["lulus"], "label": "Total Lulus Program", "datatype": "Int", "indicator": "Green"},
    ]

javascript:
frappe.query_reports["Durasi Penyelesaian Level Calistung"] = {
    filters: [
        { fieldname: "dari_tanggal", label: __("Lulus L3 Dari Tanggal"), fieldtype: "Date", description: __("Opsional - saring murid berdasar tanggal Lulus Level 3.") },
        { fieldname: "sampai_tanggal", label: __("Lulus L3 Sampai Tanggal"), fieldtype: "Date" },
        { fieldname: "hanya_lulus", label: __("Hanya Murid Lulus Program (L3)"), fieldtype: "Check", default: 0 },
    ],
};

report_script:
filters = filters or {}

codes = frappe.get_all(
    "Rumba Program Belajar",
    filters={"program_belajar": ["like", "%alistung%"]},
    pluck="name",
) or ["BMSK"]

exams = frappe.get_list(
    "Rumba Ujian Kenaikan Level",
    filters={"hasil": "Lulus", "status_ujian": "Final", "program": ["in", codes]},
    fields=["murid", "nama_unit", "level_diuji", "tanggal_ujian"],
    order_by="tanggal_ujian asc",
    limit_page_length=0,
)

per_murid = {}
for e in exams:
    if not e.murid:
        continue
    m = per_murid.setdefault(e.murid, {"unit": e.nama_unit, "L": {}})
    if e.level_diuji not in m["L"]:
        m["L"][e.level_diuji] = e.tanggal_ujian

dari = filters.get("dari_tanggal")
sampai = filters.get("sampai_tanggal")
hanya_lulus = int(filters.get("hanya_lulus") or 0)

data = []
acc = {"d1": [], "d2": [], "d3": [], "total": []}

for murid, info in per_murid.items():
    lv = info["L"]
    l1, l2, l3 = lv.get("Level 1"), lv.get("Level 2"), lv.get("Level 3")

    if hanya_lulus and not l3:
        continue
    if (dari or sampai):
        if not l3:
            continue
        if dari and frappe.utils.date_diff(l3, dari) < 0:
            continue
        if sampai and frappe.utils.date_diff(l3, sampai) > 0:
            continue

    konteks = frappe.db.get_value(
        "Rumba Murid", murid,
        ["nama_lengkap", "pendaftaran", "tanggal_pendaftaran"], as_dict=True,
    ) or {}

    mulai = None
    if konteks.get("pendaftaran"):
        mulai = frappe.db.get_value("Rumba Pendaftaran", konteks.get("pendaftaran"), "tanggal_mulai_belajar")
    mulai = mulai or konteks.get("tanggal_pendaftaran")

    d1 = frappe.utils.date_diff(l1, mulai) if (l1 and mulai) else None
    d2 = frappe.utils.date_diff(l2, l1) if (l2 and l1) else None
    d3 = frappe.utils.date_diff(l3, l2) if (l3 and l2) else None
    total = frappe.utils.date_diff(l3, mulai) if (l3 and mulai) else None

    for key, val in (("d1", d1), ("d2", d2), ("d3", d3), ("total", total)):
        if val is not None and val >= 0:
            acc[key].append(val)

    data.append({
        "unit": info["unit"], "murid": murid, "nama_murid": konteks.get("nama_lengkap"),
        "mulai_belajar": mulai,
        "lulus_l1": l1, "durasi_l1": d1,
        "lulus_l2": l2, "durasi_l2": d2,
        "lulus_l3": l3, "durasi_l3": d3,
        "total_hari": total,
    })

data.sort(key=lambda r: (r.get("unit") or "", r.get("nama_murid") or ""))

def hitung_rata(lst):
    if not lst:
        return None
    return round(frappe.utils.flt(sum(lst)) / len(lst), 1)

columns = [
    {"fieldname": "unit", "label": "Unit", "fieldtype": "Link", "options": "Rumba Unit", "width": 150},
    {"fieldname": "murid", "label": "NIM", "fieldtype": "Link", "options": "Rumba Murid", "width": 130},
    {"fieldname": "nama_murid", "label": "Nama Murid", "fieldtype": "Data", "width": 170},
    {"fieldname": "mulai_belajar", "label": "Mulai Belajar", "fieldtype": "Date", "width": 110},
    {"fieldname": "lulus_l1", "label": "Lulus L1", "fieldtype": "Date", "width": 100},
    {"fieldname": "durasi_l1", "label": "Durasi L1 (hari)", "fieldtype": "Int", "width": 120},
    {"fieldname": "lulus_l2", "label": "Lulus L2", "fieldtype": "Date", "width": 100},
    {"fieldname": "durasi_l2", "label": "Durasi L2 (hari)", "fieldtype": "Int", "width": 120},
    {"fieldname": "lulus_l3", "label": "Lulus L3", "fieldtype": "Date", "width": 100},
    {"fieldname": "durasi_l3", "label": "Durasi L3 (hari)", "fieldtype": "Int", "width": 120},
    {"fieldname": "total_hari", "label": "Total (hari)", "fieldtype": "Int", "width": 110},
]

if data:
    report_summary = [
        {"value": hitung_rata(acc["d1"]), "label": "Rata-rata Durasi L1 (hari)", "datatype": "Float", "indicator": "Blue"},
        {"value": hitung_rata(acc["d2"]), "label": "Rata-rata Durasi L2 (hari)", "datatype": "Float", "indicator": "Blue"},
        {"value": hitung_rata(acc["d3"]), "label": "Rata-rata Durasi L3 (hari)", "datatype": "Float", "indicator": "Blue"},
        {"value": hitung_rata(acc["total"]), "label": "Rata-rata Total (hari)", "datatype": "Float", "indicator": "Green"},
    ]
